function parseVec(s){ return String(s==null?'':s).trim().split(/[\s,;]+/).map(function(x){var v=+x; return isNaN(v)?0:v;}); }
function cosine(a,b){
  a=parseVec(a); b=parseVec(b);
  if(!a.length||!b.length) return {error:'请输入两个向量'};
  var n=Math.min(a.length,b.length);
  var dot=0,na=0,nb=0;
  for(var i=0;i<n;i++){ dot+=a[i]*b[i]; na+=a[i]*a[i]; nb+=b[i]*b[i]; }
  if(na===0||nb===0) return {error:'向量模长为零'};
  var c=dot/(Math.sqrt(na)*Math.sqrt(nb));
  return {cosine:Math.round(c*10000)/10000, equal:Math.abs(c-1)<1e-9, orthogonal:Math.abs(c)<1e-9};
}
var EXPORTS={cosine:cosine};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CosineSimForgePure = EXPORTS; }
